package com.hbm.client.coolingtower;
import com.hbm.client.model.LegacyItemTransforms;import com.hbm.machine.coolingtower.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.world.item.*;
/** Source ItemRenderBase plus exact smallT-4/S3 or largeT-3/S3.8 and common.25. */
public final class CoolingTowerItemRenderer extends BlockEntityWithoutLevelRenderer {
 private final CoolingTowerKind kind;public CoolingTowerItemRenderer(CoolingTowerKind kind){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());this.kind=kind;}
 @Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){pose.pushPose();if(LegacyItemTransforms.isHeld(context))LegacyItemTransforms.held(pose,context);else pose.translate(.5,.5,.5);if(context==ItemDisplayContext.GUI){pose.scale(1F/16,-1F/16,1F/16);pose.translate(0,2,0);pose.mulPose(Axis.XP.rotationDegrees(-30));pose.mulPose(Axis.YP.rotationDegrees(45));pose.scale(-1,-1,-1);pose.translate(0,kind==CoolingTowerKind.SMALL?-4:-3,0);float scale=kind==CoolingTowerKind.SMALL?3:3.8F;pose.scale(scale,scale,scale);}else{boolean entity=context==ItemDisplayContext.GROUND||context==ItemDisplayContext.FIXED||context==ItemDisplayContext.NONE;if(entity)pose.scale(1.5F,1.5F,1.5F);else pose.translate(.5,.25,0);pose.scale(.25F,.25F,.25F);if(context!=ItemDisplayContext.THIRD_PERSON_LEFT_HAND&&context!=ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)pose.mulPose(Axis.YP.rotationDegrees(90));}pose.scale(.25F,.25F,.25F);CoolingTowerRenderer.model(kind,pose,buffers,light,overlay);pose.popPose();}
}
